-- ===========================================================================
-- Hand-written: invariants Prisma cannot express
-- ===========================================================================

-- 1. Row-level CHECKs ----------------------------------------------------------

ALTER TABLE "finora"."currencies"
  ADD CONSTRAINT "currencies_code_format" CHECK ("code" ~ '^[A-Z]{3}$'),
  ADD CONSTRAINT "currencies_exponent_range" CHECK ("exponent" BETWEEN 0 AND 6);

ALTER TABLE "finora"."ledger_accounts"
  ADD CONSTRAINT "ledger_accounts_name_format" CHECK (
    char_length("name") BETWEEN 1 AND 100 AND "name" = btrim("name")
  ),
  ADD CONSTRAINT "ledger_accounts_updated_after_created" CHECK ("updated_at" >= "created_at");

ALTER TABLE "finora"."journal_entries"
  ADD CONSTRAINT "journal_entries_description_format" CHECK (
    char_length("description") BETWEEN 1 AND 500 AND "description" = btrim("description")
  ),
  ADD CONSTRAINT "journal_entries_idempotency_key_format" CHECK (
    "idempotency_key" IS NULL OR "idempotency_key" ~ '^[A-Za-z0-9][A-Za-z0-9._:-]{0,127}$'
  ),
  ADD CONSTRAINT "journal_entries_idempotency_fingerprint_format" CHECK (
    "idempotency_fingerprint" IS NULL OR "idempotency_fingerprint" ~ '^[0-9a-f]{64}$'
  ),
  ADD CONSTRAINT "journal_entries_idempotency_pair" CHECK (
    ("idempotency_key" IS NULL) = ("idempotency_fingerprint" IS NULL)
  ),
  ADD CONSTRAINT "journal_entries_posted_at_matches_status" CHECK (
    ("status" = 'posted') = ("posted_at" IS NOT NULL)
  ),
  ADD CONSTRAINT "journal_entries_posted_after_created" CHECK ("posted_at" IS NULL OR "posted_at" >= "created_at"),
  ADD CONSTRAINT "journal_entries_updated_after_created" CHECK ("updated_at" >= "created_at"),
  ADD CONSTRAINT "journal_entries_no_self_reference" CHECK (
    "reverses_entry_id" IS DISTINCT FROM "id" AND "replaces_entry_id" IS DISTINCT FROM "id"
  ),
  ADD CONSTRAINT "journal_entries_single_correction_role" CHECK (
    "reverses_entry_id" IS NULL OR "replaces_entry_id" IS NULL
  );

ALTER TABLE "finora"."journal_lines"
  ADD CONSTRAINT "journal_lines_amount_positive" CHECK ("amount_minor" > 0),
  ADD CONSTRAINT "journal_lines_line_no_positive" CHECK ("line_no" >= 1),
  ADD CONSTRAINT "journal_lines_memo_format" CHECK (
    "memo" IS NULL OR (char_length("memo") BETWEEN 1 AND 500 AND "memo" = btrim("memo"))
  );

-- 2. Reference data ------------------------------------------------------------
-- Must match KNOWN_CURRENCIES in src/domain/money/currency.ts (a test checks).
INSERT INTO "finora"."currencies" ("code", "exponent") VALUES
  ('INR', 2), ('USD', 2), ('EUR', 2), ('GBP', 2), ('JPY', 0), ('KWD', 3);

-- Changing a code or exponent would reinterpret every stored amount.
CREATE FUNCTION "finora"."currencies_guard"() RETURNS trigger
  LANGUAGE plpgsql
  SET search_path = ''
AS $$
BEGIN
  RAISE EXCEPTION 'finora.ledger: currencies are immutable; add a new currency instead'
    USING ERRCODE = 'integrity_constraint_violation';
END;
$$;

CREATE TRIGGER "currencies_guard"
  BEFORE UPDATE ON "finora"."currencies"
  FOR EACH ROW EXECUTE FUNCTION "finora"."currencies_guard"();

-- 3. Ledger accounts -------------------------------------------------------------
-- Database-assigned audit timestamps; owner, kind and currency never change
-- (lines are interpreted through them).
CREATE FUNCTION "finora"."ledger_accounts_guard"() RETURNS trigger
  LANGUAGE plpgsql
  SET search_path = ''
AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    NEW.created_at := now();
    NEW.updated_at := NEW.created_at;
    RETURN NEW;
  END IF;
  IF NEW.id <> OLD.id OR NEW.owner_id <> OLD.owner_id OR NEW.kind <> OLD.kind
     OR NEW.currency_code <> OLD.currency_code OR NEW.created_at <> OLD.created_at THEN
    RAISE EXCEPTION 'finora.ledger: a ledger account''s id, owner, kind, currency and creation time are immutable'
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  NEW.updated_at := greatest(now(), OLD.updated_at);
  RETURN NEW;
END;
$$;

CREATE TRIGGER "ledger_accounts_guard"
  BEFORE INSERT OR UPDATE ON "finora"."ledger_accounts"
  FOR EACH ROW EXECUTE FUNCTION "finora"."ledger_accounts_guard"();

-- 4. Journal entries: lifecycle and immutability -----------------------------------
-- Entries are inserted as drafts; the only permitted change of a posted entry
-- is none at all. Draft -> posted stamps posted_at with database time.
CREATE FUNCTION "finora"."journal_entries_guard"() RETURNS trigger
  LANGUAGE plpgsql
  SET search_path = ''
AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'draft' OR NEW.posted_at IS NOT NULL THEN
      RAISE EXCEPTION 'finora.ledger: journal entries are created as drafts and posted afterwards'
        USING ERRCODE = 'integrity_constraint_violation';
    END IF;
    NEW.created_at := now();
    NEW.updated_at := NEW.created_at;
    RETURN NEW;
  END IF;

  IF OLD.status = 'posted' THEN
    RAISE EXCEPTION 'finora.ledger: posted journal entries are immutable; post a reversal instead'
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;

  IF NEW.id <> OLD.id OR NEW.owner_id <> OLD.owner_id OR NEW.created_at <> OLD.created_at
     OR NEW.idempotency_key IS DISTINCT FROM OLD.idempotency_key
     OR NEW.idempotency_fingerprint IS DISTINCT FROM OLD.idempotency_fingerprint
     OR NEW.reverses_entry_id IS DISTINCT FROM OLD.reverses_entry_id
     OR NEW.replaces_entry_id IS DISTINCT FROM OLD.replaces_entry_id THEN
    RAISE EXCEPTION 'finora.ledger: a journal entry''s identity, owner, idempotency key and correction links are immutable'
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;

  IF NEW.status = 'posted' THEN
    NEW.posted_at := now();
  ELSIF NEW.posted_at IS NOT NULL THEN
    RAISE EXCEPTION 'finora.ledger: posted_at is set only by posting'
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  NEW.updated_at := greatest(now(), OLD.updated_at);
  RETURN NEW;
END;
$$;

CREATE TRIGGER "journal_entries_guard"
  BEFORE INSERT OR UPDATE OR DELETE ON "finora"."journal_entries"
  FOR EACH ROW EXECUTE FUNCTION "finora"."journal_entries_guard"();

-- 5. Journal lines: only drafts can gain or lose lines; lines are never updated.
-- SECURITY DEFINER so the parent lookup and row lock see the true entry state
-- regardless of the caller's RLS context. The lookup is restricted to the
-- line's own owner, so it reveals nothing about other owners' entries (a
-- mismatched owner falls through to the composite foreign key, which rejects it).
-- Locking the parent FOR UPDATE serialises line changes against posting:
-- a line write that races a concurrent post waits, then sees `posted`.
CREATE FUNCTION "finora"."journal_lines_guard"() RETURNS trigger
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path = ''
AS $$
DECLARE
  line finora.journal_lines%ROWTYPE;
  parent_status finora.journal_entry_status;
BEGIN
  IF TG_OP = 'UPDATE' THEN
    RAISE EXCEPTION 'finora.ledger: journal lines are immutable; replace a draft''s lines by deleting and inserting'
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;
  line := CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;

  SELECT e.status INTO parent_status
    FROM finora.journal_entries AS e
   WHERE e.id = line.entry_id AND e.owner_id = line.owner_id
     FOR UPDATE;

  IF NOT FOUND THEN
    -- DELETE: the parent draft is being deleted in this statement (cascade).
    -- INSERT: the composite foreign key rejects the missing parent.
    IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
    RETURN NEW;
  END IF;

  IF parent_status <> 'draft' THEN
    RAISE EXCEPTION 'finora.ledger: lines of a posted journal entry cannot be added or removed'
      USING ERRCODE = 'integrity_constraint_violation';
  END IF;

  IF TG_OP = 'DELETE' THEN RETURN OLD; END IF;
  NEW.created_at := now();
  RETURN NEW;
END;
$$;

CREATE TRIGGER "journal_lines_guard"
  BEFORE INSERT OR UPDATE OR DELETE ON "finora"."journal_lines"
  FOR EACH ROW EXECUTE FUNCTION "finora"."journal_lines_guard"();

-- No one (including the migration role) erases history in bulk.
CREATE FUNCTION "finora"."ledger_no_truncate"() RETURNS trigger
  LANGUAGE plpgsql
  SET search_path = ''
AS $$
BEGIN
  RAISE EXCEPTION 'finora.ledger: % cannot be truncated', TG_TABLE_NAME
    USING ERRCODE = 'integrity_constraint_violation';
END;
$$;

CREATE TRIGGER "journal_entries_no_truncate"
  BEFORE TRUNCATE ON "finora"."journal_entries"
  FOR EACH STATEMENT EXECUTE FUNCTION "finora"."ledger_no_truncate"();
CREATE TRIGGER "journal_lines_no_truncate"
  BEFORE TRUNCATE ON "finora"."journal_lines"
  FOR EACH STATEMENT EXECUTE FUNCTION "finora"."ledger_no_truncate"();

-- 6. Aggregate invariants, checked at COMMIT ------------------------------------
-- A row CHECK cannot see sibling lines, so balancing is enforced by DEFERRABLE
-- INITIALLY DEFERRED constraint triggers: a multi-line entry can be built and
-- posted within one transaction, and the transaction cannot commit unless every
-- touched entry is valid. SET CONSTRAINTS ... IMMEDIATE only moves the check
-- earlier; it cannot skip it. A posted entry must:
--   * have at least one line, and balance (debits = credits) per currency;
--   * if it is a reversal: reverse a posted, non-reversal entry and offset it
--     exactly, account by account;
--   * if it is a replacement: replace an entry that has a posted reversal.
-- Reversal and replacement links are only valid on posted entries.
CREATE FUNCTION "finora"."assert_journal_entry_valid"(target uuid) RETURNS void
  LANGUAGE plpgsql
  SET search_path = ''
AS $$
DECLARE
  entry finora.journal_entries%ROWTYPE;
  original finora.journal_entries%ROWTYPE;
BEGIN
  SELECT * INTO entry FROM finora.journal_entries WHERE id = target;
  IF NOT FOUND THEN
    RETURN; -- a draft deleted later in the same transaction
  END IF;

  IF entry.status = 'draft' THEN
    IF entry.reverses_entry_id IS NOT NULL OR entry.replaces_entry_id IS NOT NULL THEN
      RAISE EXCEPTION 'finora.ledger: reversal and replacement entries must be posted in the transaction that creates them'
        USING ERRCODE = 'check_violation';
    END IF;
    RETURN;
  END IF;

  IF NOT EXISTS (SELECT 1 FROM finora.journal_lines WHERE entry_id = target) THEN
    RAISE EXCEPTION 'finora.ledger: a posted journal entry must have lines'
      USING ERRCODE = 'check_violation';
  END IF;

  IF EXISTS (
    SELECT 1 FROM finora.journal_lines
     WHERE entry_id = target
     GROUP BY currency_code
    HAVING sum(CASE side WHEN 'debit' THEN amount_minor ELSE -amount_minor END) <> 0
  ) THEN
    RAISE EXCEPTION 'finora.ledger: posted journal entry is unbalanced'
      USING ERRCODE = 'check_violation';
  END IF;

  IF entry.reverses_entry_id IS NOT NULL THEN
    SELECT * INTO original FROM finora.journal_entries WHERE id = entry.reverses_entry_id;
    IF original.status <> 'posted' OR original.reverses_entry_id IS NOT NULL THEN
      RAISE EXCEPTION 'finora.ledger: only a posted, non-reversal entry can be reversed'
        USING ERRCODE = 'check_violation';
    END IF;
    IF EXISTS (
      SELECT 1
        FROM (SELECT account_id, sum(CASE side WHEN 'debit' THEN amount_minor ELSE -amount_minor END) AS net
                FROM finora.journal_lines WHERE entry_id = target GROUP BY account_id) AS r
        FULL JOIN
             (SELECT account_id, sum(CASE side WHEN 'debit' THEN amount_minor ELSE -amount_minor END) AS net
                FROM finora.journal_lines WHERE entry_id = original.id GROUP BY account_id) AS o
          USING (account_id)
       WHERE coalesce(r.net, 0) <> -coalesce(o.net, 0)
    ) THEN
      RAISE EXCEPTION 'finora.ledger: a reversal must exactly offset the original entry'
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;

  IF entry.replaces_entry_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM finora.journal_entries
     WHERE reverses_entry_id = entry.replaces_entry_id AND status = 'posted'
  ) THEN
    RAISE EXCEPTION 'finora.ledger: a replacement requires the original entry to be reversed'
      USING ERRCODE = 'check_violation';
  END IF;
END;
$$;

-- SECURITY DEFINER: the check must see every line of the entry, whatever RLS
-- context the transaction happens to hold at COMMIT.
CREATE FUNCTION "finora"."journal_entries_validate"() RETURNS trigger
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path = ''
AS $$
BEGIN
  PERFORM finora.assert_journal_entry_valid(NEW.id);
  RETURN NULL;
END;
$$;

CREATE FUNCTION "finora"."journal_lines_validate"() RETURNS trigger
  LANGUAGE plpgsql
  SECURITY DEFINER
  SET search_path = ''
AS $$
BEGIN
  PERFORM finora.assert_journal_entry_valid(
    CASE WHEN TG_OP = 'DELETE' THEN OLD.entry_id ELSE NEW.entry_id END
  );
  RETURN NULL;
END;
$$;

CREATE CONSTRAINT TRIGGER "journal_entries_validate"
  AFTER INSERT OR UPDATE ON "finora"."journal_entries"
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION "finora"."journal_entries_validate"();

CREATE CONSTRAINT TRIGGER "journal_lines_validate"
  AFTER INSERT OR DELETE ON "finora"."journal_lines"
  DEFERRABLE INITIALLY DEFERRED
  FOR EACH ROW EXECUTE FUNCTION "finora"."journal_lines_validate"();

REVOKE ALL ON FUNCTION "finora"."currencies_guard"() FROM PUBLIC;
REVOKE ALL ON FUNCTION "finora"."ledger_accounts_guard"() FROM PUBLIC;
REVOKE ALL ON FUNCTION "finora"."journal_entries_guard"() FROM PUBLIC;
REVOKE ALL ON FUNCTION "finora"."journal_lines_guard"() FROM PUBLIC;
REVOKE ALL ON FUNCTION "finora"."ledger_no_truncate"() FROM PUBLIC;
REVOKE ALL ON FUNCTION "finora"."assert_journal_entry_valid"(uuid) FROM PUBLIC;
REVOKE ALL ON FUNCTION "finora"."journal_entries_validate"() FROM PUBLIC;
REVOKE ALL ON FUNCTION "finora"."journal_lines_validate"() FROM PUBLIC;

-- 7. Privileges and RLS -----------------------------------------------------------
-- Least privilege for the runtime role: no UPDATE of accounts or lines, no
-- DELETE of entries, UPDATE of entries limited to the status column (posting),
-- no TRUNCATE/REFERENCES/TRIGGER anywhere.
DO $$
DECLARE
  api_role text;
BEGIN
  FOREACH api_role IN ARRAY ARRAY['anon', 'authenticated', 'service_role', 'authenticator']
  LOOP
    IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = api_role) THEN
      EXECUTE format(
        'REVOKE ALL ON finora.currencies, finora.ledger_accounts, finora.journal_entries, finora.journal_lines FROM %I',
        api_role);
    END IF;
  END LOOP;
END
$$;
REVOKE ALL ON "finora"."currencies", "finora"."ledger_accounts", "finora"."journal_entries", "finora"."journal_lines" FROM PUBLIC;

GRANT SELECT ON "finora"."currencies" TO finora_app;
GRANT SELECT, INSERT ON "finora"."ledger_accounts" TO finora_app;
GRANT SELECT, INSERT ON "finora"."journal_entries" TO finora_app;
GRANT UPDATE ("status") ON "finora"."journal_entries" TO finora_app;
GRANT SELECT, INSERT, DELETE ON "finora"."journal_lines" TO finora_app;

ALTER TABLE "finora"."currencies" ENABLE ROW LEVEL SECURITY;
CREATE POLICY "currencies_read" ON "finora"."currencies"
  AS PERMISSIVE FOR SELECT TO finora_app USING (true);

SELECT finora.apply_owner_isolation('finora.ledger_accounts');
SELECT finora.apply_owner_isolation('finora.journal_entries');
SELECT finora.apply_owner_isolation('finora.journal_lines');
